Translate the following GNU C++17 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#pragma GCC optimize ("O3")
#include <iostream>
#include <cmath>
#include <limits>
using namespace std;
using lld = long long int;

lld gcd(lld a, lld b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}

#define CHECK_CANDIDATE(i) \
    do { \
        long double cur = std::fabs((long double)(i) / (long double)j - target); \
        if (cur < best) { \
            best = cur; \
            x = (int)(i); \
            y = (int)j; \
        } \
    } while (0)

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int a, b, n;
    cin >> a >> b >> n;
    int x, y;
    long double best = std::numeric_limits<long double>::infinity();
    long double target = (long double)a / (long double)b;
    for (lld j = 1; j <= n; ++j) {
        lld base = (j * a) / b;
        CHECK_CANDIDATE(base - 1);
        CHECK_CANDIDATE(base);
        CHECK_CANDIDATE(base + 1);
    }
    cout << x / gcd(x, y) << "/" << y / gcd(x, y);
}
